        mutual = max(core_distance[u], core_distance[v], d)
        edges.append((mutual, u, v))

    edges.sort(key=lambda x: x[0])

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == len(nodes) - 1:
                break

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
